/*
**	lib_initscr.c
**
**	The routines initscr(), and termname().
**
*/

#include <curses.priv.h>

#if HAVE_SYS_TERMIO_H
#include <sys/termio.h>		/* needed for ISC */
#endif

MODULE_ID("$Id: lib_initscr.c,v 1.53 2026/05/30 22:10:47 tom Exp $")

NCURSES_EXPORT(WINDOW *)
initscr(void)
{
    WINDOW *result;

    START_TRACE();
    T((T_CALLED("initscr()")));

    _nc_init_pthreads();
    _nc_lock_global(curses);

    /* Portable applications must not call initscr() more than once */
    if (!_nc_globals.init_screen) {
	const char *env;
	char *name;

	_nc_globals.init_screen = TRUE;

	env = getenv("TERM");
	(void) VALID_TERM_ENV(env, "unknown");

	if ((name = strdup(env)) == NULL) {
	    fprintf(stderr, "ncurses: cannot allocate %d bytes of"
		    "memory for $TERM; exiting\n", (int) strlen(env));
	    ExitProgram(EXIT_FAILURE);
	}
#ifdef __CYGWIN__
	/*
	 * 2002/9/21
	 * Work around a bug in Cygwin.  Full-screen subprocesses run from
	 * bash, in turn spawned from another full-screen process, will dump
	 * core when attempting to write to stdout.  Opening /dev/tty
	 * explicitly seems to fix the problem.
	 */
	if (NC_ISATTY(fileno(stdout))) {
	    FILE *fp = fopen("/dev/tty", "w");
	    if (fp != 0 && NC_ISATTY(fileno(fp))) {
		fclose(stdout);
		dup2(fileno(fp), STDOUT_FILENO);
		stdout = fdopen(STDOUT_FILENO, "w");
	    }
	}
#endif
	if (newterm(name, stdout, stdin) == NULL) {
	    fprintf(stderr, "ncurses: cannot initialize terminal type"
		    " ($TERM=\"%s\"); exiting\n", name);
	    ExitProgram(EXIT_FAILURE);
	}

	/* def_shell_mode - done in newterm/_nc_setupscreen */
#if NCURSES_SP_FUNCS
	NCURSES_SP_NAME(def_prog_mode)(CURRENT_SCREEN);
#else
	def_prog_mode();
#endif
	free(name);
    }
    result = stdscr;
    _nc_unlock_global(curses);

    returnWin(result);
